pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set MinSum to 1 ether
        c.SetMinSum(1 ether);
        // Initialize the contract (in reference, this prevents further SetMinSum calls)
        c.Initialized();
        // Give user address(this) 2 ether and put 2 ether into contract
        vm.deal(address(this), 2 ether);
        c.Put{value: 2 ether}(0);
        // Now try to collect 1 ether (balance >= MinSum and >= _am, timestamp > unlockTime)
        vm.warp(block.timestamp + 1);
        // In the reference, MinSum stays 1 ether, so Collect should succeed
        // In the buggy version, SetMinSum can be called again later, but here it was called before Init
        // Actually we need to exploit that in buggy version SetMinSum can be called after Init to change MinSum
        // Let's resetup: first call SetMinSum (initial), then call Initialized, then call SetMinSum again in buggy version
        // But we cannot call SetMinSum after Init in reference because it reverts.
        // To make them diverge on Collect after a second SetMinSum call, we need to call SetMinSum after Init (only possible in buggy)
        // So: call SetMinSum(1 ether), Init, then call SetMinSum(10 ether) — reference reverts this second call, buggy allows it.
        // Then the caller's balance is 1 ether; in reference MinSum=1 => Collect succeeds; in buggy MinSum=10 => Collect fails.

        // Re-deploy for clarity (new test)
        c = new C();
        c.SetMinSum(1 ether);
        c.Initialized();
        // In buggy, this next call will succeed and change MinSum to 10 ether
        // In reference, it reverts and MinSum stays 1 ether.
        // But from test perspective, we cannot directly test revert differences until we call Collect.
        // So we call Collect after trying to change MinSum:
        vm.deal(address(this), 2 ether);
        c.Put{value: 2 ether}(0);
        vm.warp(block.timestamp + 1);
        // Now call SetMinSum again (in reference reverts, but we can use try/catch to ignore)
        // Actually we want to observe MinSum after this call: in reference it's 1, in buggy it's 10.
        // Then Collect(1 ether) in reference succeeds, in buggy fails because MinSum=10 > balance=1.

        // Call SetMinSum (second) – in reference reverts, but we still see original MinSum; in buggy succeeds.
        (bool okSet,) = address(c).call(abi.encodeWithSignature("SetMinSum(uint256)", 10 ether));

        // Now check MinSum value before Collect
        uint minSumBefore = c.MinSum();

        // Try Collect(1 ether)
        bool okCollect;
        try c.Collect(1 ether) { okCollect = true; } catch { okCollect = false; }

        // In reference: minSumBefore == 1 ether, Collect succeeds (okCollect == true)
        // In buggy: minSumBefore == 10 ether, Collect fails because balance=1 < MinSum=10 (okCollect == false)
        // Assert the reference behavior: minSumBefore == 1 and Collect succeeds
        assertTrue(minSumBefore == 1 ether && okCollect == true);
    }
}

