    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.SetMinSum(5);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // User deposits 6 wei with lockTime = 0
        address user = address(0x123);
        vm.deal(user, 10 wei);
        vm.prank(user);
        c.Put{value: 6 wei}(0);

        // At the same timestamp, try to collect 6 wei
        vm.prank(user);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", 6));

        // In the reference, Collect reverts because block.timestamp > unlockTime is false
        // In the mutant, Collect succeeds and transfers Ether, reducing c's balance
        assertTrue(success == false || address(c).balance == 6 wei);
    }
}

