pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize the contract
        c.SetMinSum(10);
        c.Initialized();

        // Give user address some ether and deposit 7 wei with lockTime=0
        address user = address(0x1234);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.Put{value: 7}(0);  // balance=7, unlockTime=block.timestamp

        // Warp to one second later so block.timestamp > unlockTime
        vm.warp(block.timestamp + 1);

        // Attempt Collect(7) — the reference reverts (balance 7 < MinSum 10), the mutant succeeds
        bool ok;
        vm.prank(user);
        try c.Collect(7) { ok = true; } catch { ok = false; }

        // Reference: ok == false (revert); Mutant: ok == true (sends ether).
        assertTrue(!ok);
    }
}

