pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Initialize contract and set MinSum
        c.Initialized();
        c.SetMinSum(5);

        // User deposits 6 wei with lockTime=0
        address user = address(0x1);
        vm.deal(user, 6);
        vm.prank(user);
        c.Put{value: 6}(0);

        // Try to collect 6 wei at the same timestamp
        bool ok;
        vm.prank(user);
        try c.Collect(6) {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference should revert (block.timestamp == unlockTime, so condition false)
        // Buggy version would succeed, reducing contract balance
        assertTrue(!ok, "Collect should revert because timestamp condition not met");
    }
}
